/** The variant URL for a source path and width (see gen-image-variants.ts). */
export function variantUrl(src: string, width: number): string {
  return `/images/_variants/${src.replace(/^\/images\//, '').replace(/\.[^.]+$/, '')}-${width}.webp`;
}
